<?php
require_once __DIR__.'/Database.php'; require_once __DIR__.'/Finance.php';
final class App {
 public static function run(): void { session_start(); $pdo=Database::connection(); $path=parse_url($_SERVER['REQUEST_URI'],PHP_URL_PATH) ?: '/'; if($_SERVER['REQUEST_METHOD']==='POST') self::post($pdo); self::page($pdo,$path); }
 private static function post(PDO $db): void { $action=$_POST['action']??''; if($action==='participant'){ $s=$db->prepare('INSERT INTO participants(document,full_name,phone,email) VALUES(?,?,?,?)');$s->execute([trim($_POST['document']),trim($_POST['full_name']),trim($_POST['phone']??''),trim($_POST['email']??'')]); } elseif($action==='contribution'){ $s=$db->prepare('INSERT INTO contributions(participant_id,year,month,amount_due,amount_paid) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE amount_paid=VALUES(amount_paid)');$s->execute([(int)$_POST['participant_id'],(int)$_POST['year'],(int)$_POST['month'],100000,min(100000,max(0,(float)($_POST['amount']??0)))]); } elseif($action==='loan'){ $type=$_POST['loan_type']??'PARTICIPANT';$rate=Finance::validateLoan($type,0,$_POST['referred_name']??'',$_POST['referred_document']??'');$rows=Finance::amortization((float)$_POST['principal'],$rate,(int)$_POST['term_months'],new DateTimeImmutable($_POST['start_date']));$s=$db->prepare('INSERT INTO loans(participant_id,principal,monthly_rate,term_months,start_date,loan_type,referred_name,referred_document) VALUES(?,?,?,?,?,?,?,?)');$s->execute([(int)$_POST['participant_id'],$_POST['principal'],$rate,$_POST['term_months'],$_POST['start_date'],$type,$_POST['referred_name']??null,$_POST['referred_document']??null]);$id=$db->lastInsertId();$i=$db->prepare('INSERT INTO loan_installments(loan_id,installment_number,due_date,principal_amount,interest_amount,total_amount) VALUES(?,?,?,?,?,?)');foreach($rows as $r)$i->execute([$id,$r['number'],$r['due_date'],$r['principal'],$r['interest'],$r['total']]); } header('Location: '.$_SERVER['REQUEST_URI']); exit; }
 private static function page(PDO $db,string $path): void { $participants=$db->query('SELECT * FROM participants ORDER BY active DESC,full_name')->fetchAll();$year=(int)($_GET['year']??date('Y'));$loans=$db->query('SELECT l.*,p.full_name FROM loans l JOIN participants p ON p.id=l.participant_id ORDER BY l.start_date DESC')->fetchAll(); $active=array_filter($participants,fn($p)=>(int)$p['active']===1); $title=match(true){str_starts_with($path,'/participants')=>'Participantes',str_starts_with($path,'/loans')=>'Préstamos',str_starts_with($path,'/reports')=>'Reportes',default=>'Ahorros'}; echo self::head($title); echo '<nav><a class="brand" href="/">Ｎ Natillera <small>FINANCIERA</small></a><a href="/">Ahorros</a><a href="/participants">Participantes</a><a href="/loans">Préstamos</a><a href="/reports/annual">Reportes</a></nav><main>'; if($path==='/participants')self::participants($participants);elseif($path==='/loans')self::loans($loans,$participants);elseif(str_starts_with($path,'/reports'))self::report($db,$active,$loans,$year);else self::savings($db,$active,$year); echo '</main>'.self::foot(); }
 private static function participants(array $ps): void { echo '<section class="hero"><span>GESTIÓN DE PARTICIPANTES</span><h1>Participantes</h1><button onclick="document.querySelector(\'.modal\').classList.add(\'open\')">＋ Agregar participante</button></section><section class="grid">';foreach($ps as $p)echo '<article class="card"><b>'.htmlspecialchars($p['full_name']).'</b><small>Documento '.htmlspecialchars($p['document']).'</small><small>'.htmlspecialchars($p['phone']??'').'</small><span class="badge">'.((int)$p['active']?'Activo':'Inactivo').'</span></article>';echo '</section><div class="modal"><div class="modal-box"><button onclick="this.closest(\'.modal\').classList.remove(\'open\')">×</button><h2>Nuevo participante</h2><form method="post"><input type="hidden" name="action" value="participant"><input name="document" placeholder="Documento" required><input name="full_name" placeholder="Nombre completo" required><input name="phone" placeholder="Teléfono"><input name="email" type="email" placeholder="Correo"><button>Guardar participante</button></form></div></div>'; }
 private static function savings(PDO $db,array $ps,int $year): void { echo '<section class="hero"><span>GESTIÓN DE AHORROS</span><h1>Control de cuotas '.$year.'</h1><form><input name="year" value="'.$year.'"><button>Filtrar</button></form></section><div class="table-wrap"><table><thead><tr><th>Participante</th>';for($m=1;$m<=11;$m++)echo '<th>'.date('F',mktime(0,0,0,$m,1)).'</th>';echo '</tr></thead><tbody>';foreach($ps as $p){echo '<tr><th>'.htmlspecialchars($p['full_name']).'</th>';for($m=1;$m<=11;$m++){echo '<td><small>'.date('F',mktime(0,0,0,$m,1)).'</small><form method="post"><input type="hidden" name="action" value="contribution"><input type="hidden" name="participant_id" value="'.$p['id'].'"><input type="hidden" name="year" value="'.$year.'"><input type="hidden" name="month" value="'.$m.'"><input name="amount" type="number" placeholder="100000"><button>Guardar</button></form></td>';}echo '</tr>';}echo '</tbody></table></div>'; }
 private static function loans(array $ls,array $ps): void { echo '<section class="hero"><span>GESTIÓN DE PRÉSTAMOS</span><h1>Préstamos</h1><button onclick="document.querySelector(\'.modal\').classList.add(\'open\')">＋ Nuevo préstamo</button></section><div class="grid">';foreach($ls as $l)echo '<article class="card"><b>'.htmlspecialchars($l['full_name']).'</b><small>Capital $'.number_format($l['principal'],0,',','.').' · '.($l['monthly_rate']*100).'% mensual</small><span class="badge">'.htmlspecialchars($l['status']).'</span></article>';echo '</div><div class="modal"><div class="modal-box"><button onclick="this.closest(\'.modal\').classList.remove(\'open\')">×</button><h2>Nuevo préstamo</h2><form method="post"><input type="hidden" name="action" value="loan"><select name="participant_id">';foreach($ps as $p)echo '<option value="'.$p['id'].'">'.htmlspecialchars($p['full_name']).'</option>';echo '</select><input name="principal" type="number" placeholder="Capital" required><input name="term_months" type="number" placeholder="Meses" required><input name="start_date" type="date" required><select name="loan_type"><option value="PARTICIPANT">Propio 5%</option><option value="REFERRED">Referido 10%</option></select><button>Crear plan</button></form></div></div>'; }
 private static function report(PDO $db,array $ps,array $ls,int $year): void { $result=(new Repository($db))->annualReport($year);$interest=(float)$result['total_interest'];$share=(float)$result['share'];echo '<div class="report-hero"><div><span class="eyebrow">CIERRE ANUAL</span><h1>Reporte financiero '.$year.'</h1><p class="muted">Resumen del ahorro acumulado y las ganancias generadas.</p></div><div class="report-badge">Distribución igualitaria</div></div><form class="report-filter" method="get"><label>Año del cierre</label><input name="year" type="number" value="'.$year.'"><button>Consultar año</button></form><div class="report-stats"><div class="report-stat green"><small>Participantes activos</small><strong>'.count($ps).'</strong></div><div class="report-stat blue"><small>Intereses consolidados</small><strong>$'.number_format($interest,0,',','.').'</strong></div><div class="report-stat purple"><small>Ganancia igual por participante</small><strong>$'.number_format($share,0,',','.').'</strong></div></div><div class="report-table"><table><thead><tr><th>Participante</th><th>Ahorro 11 meses</th><th>Préstamos propios</th><th>Préstamos a referidos</th><th>Interés generado</th><th>Parte igual</th><th>Total a entregar</th></tr></thead><tbody>';foreach($result['rows'] as $row){echo '<tr><td><strong>'.self::e($row['participant']['full_name']).'</strong><small>'.self::e($row['participant']['document']).'</small></td><td>$'.number_format($row['savings'],0,',','.').'</td><td>'.$row['own_count'].'</td><td>'.$row['referred_count'].'</td><td>$'.number_format($row['interest_generated'],0,',','.').'</td><td class="share">$'.number_format($row['interest_share'],0,',','.').'</td><td class="money">$'.number_format($row['savings']+$row['interest_share'],0,',','.').'</td></tr>';}echo '</tbody></table></div><section class="method"><button class="method-toggle" type="button">ⓘ ¿Cómo se calcula?</button><div class="method-popover">Se suman los intereses de las cuotas con vencimiento dentro del año consultado, tanto de préstamos propios al 5% como de préstamos a referidos al 10%. La ganancia total se divide en partes iguales entre los participantes activos y se suma al ahorro individual de enero a noviembre.</div></section>'; }
 private static function head(string $title): string {return '<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.htmlspecialchars($title).' · Natillera</title><link rel="manifest" href="/static/manifest.webmanifest"><link rel="stylesheet" href="/static/app.css"><link rel="stylesheet" href="/static/pwa.css"><style>body{margin:0;background:#f4faf7;color:#15352e;font:16px Arial}nav{display:flex;gap:12px;align-items:center;padding:22px;flex-wrap:wrap;background:#083b32}nav a{color:white;text-decoration:none;padding:12px 18px;border-radius:14px;background:#185447}.brand{font-weight:bold;background:#20ad7b!important;margin-right:auto}.brand small{display:block;font-size:9px}.page,main{padding:28px;max-width:1200px;margin:auto}.hero{padding:24px 0}.hero span{color:#16845e;font-size:11px;font-weight:bold;letter-spacing:2px}.hero h1{font-size:38px}.hero button,button{background:#0d4035;color:white;border:0;border-radius:12px;padding:12px 18px;font-weight:bold;cursor:pointer}.grid,.stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:16px}.card{background:white;border-radius:22px;padding:22px;box-shadow:0 8px 26px #16463812}.card>*{display:block;margin:6px 0}.badge{color:#087d55;font-weight:bold}.table-wrap{overflow:auto;background:white;border-radius:20px}.table-wrap table{border-collapse:collapse;min-width:1200px;width:100%}th,td{padding:16px;border-bottom:1px solid #e4eee9;text-align:left}td form{display:grid;gap:6px}td input{width:90px}.modal{display:none;position:fixed;inset:0;background:#05372dbb;place-items:center;padding:18px;z-index:3}.modal.open{display:grid}.modal-box{background:white;border-radius:24px;padding:28px;width:min(500px,100%)}.modal-box form{display:grid;gap:10px}.modal-box input,.modal-box select{padding:13px;border:1px solid #cbded6;border-radius:10px}@media(max-width:600px){.hero h1{font-size:30px}nav{padding:14px}nav a{padding:9px 11px;font-size:13px}.brand{flex-basis:100%}}</style></head><body>';}
 private static function foot(): string{return '<script>if("serviceWorker"in navigator)navigator.serviceWorker.register("/static/sw.js")</script></body></html>';}
}
